  3→/* ── SUPER DUPER Sidebar ─────────────────────────────────────────────
  4→ *  Registers a sidebar tab in ComfyUI's extension manager.
  5→ *  Chat interface with WebSocket connection to agent brain.
  6→ * ──────────────────────────────────────────────────────────────────── */
  7→
  8→const SIDEBAR_ID = "superduper";
  9→const SIDEBAR_TITLE = "SUPER DUPER";
 10→
 11→/* ── Load stylesheet ──────────────────────────────────────────────── */
 12→
 13→const cssLink = document.createElement("link");
 14→cssLink.rel = "stylesheet";
 15→cssLink.href = new URL("../css/superduper.css", import.meta.url).href;
 16→document.head.appendChild(cssLink);
 17→
