  color: #eee;
  font-size: 13px;
  outline: none;
  transition: border-color 0.15s;
}

.sd-input:focus {
  border-color: #4a9eff;
}

.sd-input::placeholder {
  color: #666;
}

.sd-send-btn {
  background: #4a9eff;
  color: #fff;
  border: none;
  border-radius: 6px;
  padding: 8px 14px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s;
  flex-shrink: 0;
}

.sd-send-btn:hover {
  background: #3a8eef;
}

.sd-send-btn:active {
  background: #2a7edf;
}

.sd-send-btn:disabled {
  background: #555;
  cursor: not-allowed;
}

/* ── Scrollbar ────────────────────────────────────────────────────── */

.sd-messages::-webkit-scrollbar {
  width: 6px;
}

.sd-messages::-webkit-scrollbar-track {
  background: transparent;
}

.sd-messages::-webkit-scrollbar-thumb {
  background: #444;
  border-radius: 3px;
}

.sd-messages::-webkit-scrollbar-thumb:hover {
  background: #555;
}

